export fn lee_breadth_first_search(v:[*]const i64,n:usize)i64{if(n<6 or n>70)return -2;const r=v[0];const c=v[1];const sr=v[2];const sc=v[3];const dr=v[4];const dc=v[5];if(r<1 or r>8 or c<1 or c>8 or n!=6+@as(usize,@intCast(r*c)) or sr<0 or sr>=r or dr<0 or dr>=r or sc<0 or sc>=c or dc<0 or dc>=c)return -2;var cells:[64]i64=@splat(0);var dist:[64]i64=@splat(-1);var q:[64]usize=@splat(0);for(0..@as(usize,@intCast(r*c)))|i|{cells[i]=v[6+i];if(cells[i]!=0 and cells[i]!=1)return -2;}const s:usize=@intCast(sr*c+sc);const t:usize=@intCast(dr*c+dc);if(cells[s]==0 or cells[t]==0)return -1;var h:usize=0;var z:usize=1;q[0]=s;dist[s]=0;while(h<z){const u=q[h];h+=1;if(u==t)return dist[u];const y:i64=@intCast(u/@as(usize,@intCast(c)));const x:i64=@intCast(u%@as(usize,@intCast(c)));const ys=[_]i64{y-1,y,y,y+1};const xs=[_]i64{x,x-1,x+1,x};for(0..4)|k|{if(ys[k]>=0 and ys[k]<r and xs[k]>=0 and xs[k]<c){const w:usize=@intCast(ys[k]*c+xs[k]);if(cells[w]==1 and dist[w]<0){dist[w]=dist[u]+1;q[z]=w;z+=1;}}}}return -1;}
